CREATE TABLE IF NOT EXISTS public.auth_sessions(id uuid PRIMARY KEY,actor text NOT NULL,empresa_id uuid REFERENCES public.empresas(id),expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS public.hospital_state(empresa_id uuid NOT NULL REFERENCES public.empresas(id),namespace text NOT NULL CHECK(namespace IN ('clinical','nursing-patients','nursing-operation','appointments','billing')),data jsonb,revision integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(empresa_id,namespace));
CREATE TABLE IF NOT EXISTS public.hospital_audit(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),actor text NOT NULL,action text NOT NULL,reference text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospital_folders(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),parent_id uuid,name text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(empresa_id,id),FOREIGN KEY(empresa_id,parent_id) REFERENCES public.hospital_folders(empresa_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS hospital_folder_name ON public.hospital_folders(empresa_id,coalesce(parent_id,'00000000-0000-0000-0000-000000000000'::uuid),lower(name));
CREATE TABLE IF NOT EXISTS public.hospital_files(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),folder_id uuid,name text NOT NULL,mime text NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes>=0 AND size_bytes<=10485760),content bytea NOT NULL,sha256 text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,FOREIGN KEY(empresa_id,folder_id) REFERENCES public.hospital_folders(empresa_id,id));
CREATE INDEX IF NOT EXISTS hospital_file_lookup ON public.hospital_files(empresa_id,folder_id,created_at);
CREATE TABLE IF NOT EXISTS public.hospital_messages(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),sender text NOT NULL,sender_name text NOT NULL,recipient text,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000),request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(empresa_id,sender,request_id));
CREATE INDEX IF NOT EXISTS hospital_message_lookup ON public.hospital_messages(empresa_id,created_at);
CREATE TABLE IF NOT EXISTS public.hospital_read_receipts(empresa_id uuid NOT NULL REFERENCES public.empresas(id),actor text NOT NULL,conversation text NOT NULL,read_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(empresa_id,actor,conversation));
CREATE TABLE IF NOT EXISTS public.hospital_shares(id uuid PRIMARY KEY,source_empresa_id uuid NOT NULL REFERENCES public.empresas(id),target_empresa_id uuid NOT NULL REFERENCES public.empresas(id),patient_id integer NOT NULL,subject text NOT NULL,body text NOT NULL,basis text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,read_at timestamptz,CHECK(source_empresa_id<>target_empresa_id));
CREATE INDEX IF NOT EXISTS hospital_share_inbox ON public.hospital_shares(target_empresa_id,created_at);
CREATE TABLE IF NOT EXISTS public.hospital_pharmacy(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),code text NOT NULL,name text NOT NULL,lot text NOT NULL,expiry date NOT NULL,stock numeric(16,3) NOT NULL CHECK(stock>=0),minimum numeric(16,3) NOT NULL DEFAULT 0 CHECK(minimum>=0),price numeric(16,2) NOT NULL DEFAULT 0 CHECK(price>=0),active boolean NOT NULL DEFAULT true,UNIQUE(empresa_id,code,lot));
CREATE TABLE IF NOT EXISTS public.hospital_pharmacy_moves(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),product_id uuid NOT NULL REFERENCES public.hospital_pharmacy(id),quantity numeric(16,3) NOT NULL,reason text NOT NULL,prescription_id text,item_id text,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL,UNIQUE(empresa_id,request_id));
CREATE UNIQUE INDEX IF NOT EXISTS pacientes_tenant_id ON public.pacientes(empresa_id,id);
CREATE UNIQUE INDEX IF NOT EXISTS resultados_tenant_id ON public.resultados(empresa_id,id);
CREATE UNIQUE INDEX IF NOT EXISTS faturas_tenant_id ON public.faturas(empresa_id,id);
CREATE UNIQUE INDEX IF NOT EXISTS reagentes_tenant_id ON public.reagentes(empresa_id,id);
ALTER TABLE public.resultados ADD CONSTRAINT resultados_tenant_patient FOREIGN KEY(empresa_id,paciente_id) REFERENCES public.pacientes(empresa_id,id) NOT VALID;
ALTER TABLE public.faturas ADD CONSTRAINT faturas_tenant_patient FOREIGN KEY(empresa_id,paciente_id) REFERENCES public.pacientes(empresa_id,id) NOT VALID;
ALTER TABLE public.faturas ADD CONSTRAINT faturas_tenant_result FOREIGN KEY(empresa_id,resultado_id) REFERENCES public.resultados(empresa_id,id) NOT VALID;
ALTER TABLE public.movimentos ADD CONSTRAINT movimentos_tenant_invoice FOREIGN KEY(empresa_id,fatura_id) REFERENCES public.faturas(empresa_id,id) NOT VALID;
ALTER TABLE public.stock_movimentos ADD CONSTRAINT stock_tenant_reagent FOREIGN KEY(empresa_id,reagente_id) REFERENCES public.reagentes(empresa_id,id) NOT VALID;
ALTER TABLE public.hospital_shares ADD CONSTRAINT share_tenant_patient FOREIGN KEY(source_empresa_id,patient_id) REFERENCES public.pacientes(empresa_id,id) NOT VALID;

